<?php
declare(strict_types=1);
require_once __DIR__ . '/functions.php';
require_role(['admin','teacher']);
$pdo=db();$user=current_user();$role=$user['role'];
$classSql=$role==='teacher'?'SELECT c.id,c.class_code,c.subject_name,u.full_name AS teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id WHERE c.teacher_id=? ORDER BY c.class_code':'SELECT c.id,c.class_code,c.subject_name,u.full_name AS teacher_name FROM classes c JOIN users u ON u.id=c.teacher_id ORDER BY c.class_code';
$classQuery=$pdo->prepare($classSql);$classQuery->execute($role==='teacher'?[$user['id']]:[]);$classes=$classQuery->fetchAll();
$managedIds=array_map('intval',array_column($classes,'id'));
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');$id=(int)($_POST['student_id']??0);
 try{
  if($action==='save'){
   $name=trim((string)($_POST['full_name']??''));$email=strtolower(trim((string)($_POST['email']??'')));$number=strtoupper(trim((string)($_POST['student_number']??'')));$program=trim((string)($_POST['program_year']??''));$section=strtoupper(trim((string)($_POST['section']??'')));$classId=(int)($_POST['class_id']??0);$password=(string)($_POST['password']??'');
   if(text_length($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||$number===''||$program===''||$section===''||!in_array($classId,$managedIds,true)){throw new RuntimeException('Complete all required fields and choose one of your classes.');}
   $pdo->beginTransaction();
   if($id>0){
    $ownerSql=$role==='teacher'?' AND EXISTS(SELECT 1 FROM enrollments e JOIN classes c ON c.id=e.class_id WHERE e.student_id=s.id AND c.teacher_id=?)':'';$ownerParams=[$id];if($role==='teacher')$ownerParams[]=$user['id'];$owner=$pdo->prepare('SELECT s.user_id FROM students s WHERE s.id=?'.$ownerSql);$owner->execute($ownerParams);$userId=$owner->fetchColumn();if(!$userId)throw new RuntimeException('This student is outside your class roster.');
    $uq=$pdo->prepare('UPDATE users SET full_name=?,email=? WHERE id=?');$uq->execute([$name,$email,$userId]);$sq=$pdo->prepare('UPDATE students SET student_number=?,program_year=?,section=? WHERE id=?');$sq->execute([$number,$program,$section,$id]);
    $enroll=$pdo->prepare('INSERT IGNORE INTO enrollments (student_id,class_id) VALUES (?,?)');$enroll->execute([$id,$classId]);
    $pdo->commit();flash('success','Student details updated.');
   }else{
    if(text_length($password)<8)throw new RuntimeException('Choose an initial password with at least 8 characters.');
    $uq=$pdo->prepare("INSERT INTO users (full_name,email,password_hash,role) VALUES (?,?,?,'student')");$uq->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT)]);$userId=(int)$pdo->lastInsertId();
    $sq=$pdo->prepare("INSERT INTO students (user_id,student_number,program_year,section,face_status) VALUES (?,?,?,?,'Pending')");$sq->execute([$userId,$number,$program,$section]);$studentId=(int)$pdo->lastInsertId();
    $enroll=$pdo->prepare('INSERT INTO enrollments (student_id,class_id) VALUES (?,?)');$enroll->execute([$studentId,$classId]);$pdo->commit();flash('success','Student account and class enrollment created.');
   }
  }elseif($action==='delete'&&$id>0){
   if($role==='admin'){$del=$pdo->prepare('DELETE FROM students WHERE id=?');$del->execute([$id]);if(!$del->rowCount())throw new RuntimeException('Student record not found.');flash('success','Student account removed.');}
   else{$in='('.implode(',',array_fill(0,count($managedIds),'?')).')';if(!$managedIds)throw new RuntimeException('No classes are assigned to your account.');$check=$pdo->prepare('SELECT s.user_id FROM students s WHERE s.id=? AND EXISTS(SELECT 1 FROM enrollments e JOIN classes c ON c.id=e.class_id WHERE e.student_id=s.id AND c.teacher_id=?)');$check->execute([$id,$user['id']]);$userId=$check->fetchColumn();if(!$userId)throw new RuntimeException('This student is outside your class roster.');$del=$pdo->prepare('DELETE e FROM enrollments e WHERE e.student_id=? AND e.class_id IN '.$in);$del->execute(array_merge([$id],$managedIds));$remaining=$pdo->prepare('SELECT COUNT(*) FROM enrollments WHERE student_id=?');$remaining->execute([$id]);if((int)$remaining->fetchColumn()===0){$pdo->prepare('DELETE FROM students WHERE id=?')->execute([$id]);}$note='Student removed from your class roster.';flash('success',$note);}
  }
 }catch(Throwable $exception){if($pdo->inTransaction())$pdo->rollBack();flash('error',$exception instanceof RuntimeException?$exception->getMessage():'Could not save the student. Check for duplicate email or student number.');}
 header('Location: students_manage.php');exit;
}
$term=trim((string)($_GET['q']??''));$face=(string)($_GET['face']??'');$where=[];$params=[];
if($term!==''){$where[]='(u.full_name LIKE ? OR u.email LIKE ? OR s.student_number LIKE ? OR s.program_year LIKE ? OR s.section LIKE ?)';$like='%'.$term.'%';array_push($params,$like,$like,$like,$like,$like);}
if(in_array($face,['Registered','Pending'],true)){$where[]='s.face_status=?';$params[]=$face;}
if($role==='teacher'){$where[]='EXISTS(SELECT 1 FROM enrollments et JOIN classes ct ON ct.id=et.class_id WHERE et.student_id=s.id AND ct.teacher_id=?)';$params[]=$user['id'];}
$sql='SELECT s.id,s.user_id,s.student_number,s.program_year,s.section,s.face_status,s.updated_at,u.full_name,u.email,GROUP_CONCAT(DISTINCT c.class_code ORDER BY c.class_code SEPARATOR ", ") AS classes,GROUP_CONCAT(DISTINCT e.class_id) AS class_ids';
$from=' FROM students s JOIN users u ON u.id=s.user_id LEFT JOIN enrollments e ON e.student_id=s.id LEFT JOIN classes c ON c.id=e.class_id';
$sql.=$from;
if($where)$sql.=' WHERE '.implode(' AND ',$where);$sql.=' GROUP BY s.id ORDER BY u.full_name LIMIT 200';$list=$pdo->prepare($sql);$list->execute($params);$students=$list->fetchAll();
if($role==='teacher'){$statsQuery=$pdo->prepare("SELECT COUNT(DISTINCT s.id) total,COUNT(DISTINCT IF(s.face_status='Registered',s.id,NULL)) registered,COUNT(DISTINCT IF(s.face_status='Pending',s.id,NULL)) pending FROM students s JOIN enrollments e ON e.student_id=s.id JOIN classes c ON c.id=e.class_id WHERE c.teacher_id=?");$statsQuery->execute([$user['id']]);$stats=$statsQuery->fetch();}else{$stats=$pdo->query("SELECT COUNT(*) total,SUM(face_status='Registered') registered,SUM(face_status='Pending') pending FROM students")->fetch();}
page_start('Students & classes','students_manage.php');
?>
<div class="page-heading"><div><p class="overline">CAMPUS DIRECTORY</p><h1>Students & classes</h1><p class="heading-subtitle">Manage student accounts, class enrollments, and face registration readiness.</p></div><button class="btn btn-primary heading-action" data-bs-toggle="modal" data-bs-target="#studentModal" onclick="prepareStudentModal()"><i class="bi bi-person-plus me-1"></i> Add new student</button></div>
<div class="row g-3 mb-3"><div class="col-6 col-lg-4"><article class="stat-card"><div class="stat-top"><span>Students in directory</span><span class="stat-icon icon-blue"><i class="bi bi-people"></i></span></div><div class="stat-value"><?= number_format((int)$stats['total']) ?></div><div class="stat-foot">Active student profiles</div></article></div><div class="col-6 col-lg-4"><article class="stat-card"><div class="stat-top"><span>Face registered</span><span class="stat-icon icon-green"><i class="bi bi-person-check"></i></span></div><div class="stat-value"><?= number_format((int)$stats['registered']) ?></div><div class="stat-foot">Ready for face verification</div></article></div><div class="col-12 col-lg-4"><article class="stat-card"><div class="stat-top"><span>Setup pending</span><span class="stat-icon icon-amber"><i class="bi bi-person-exclamation"></i></span></div><div class="stat-value"><?= number_format((int)$stats['pending']) ?></div><div class="stat-foot">Students to follow up</div></article></div></div>
<section class="content-card report-card"><div class="card-heading"><div><h2>Student directory</h2><p><?= count($students) ?> matching student profiles</p></div><div class="record-chip"><i class="bi bi-book me-1"></i><?= count($classes) ?> managed classes</div></div><form class="filter-bar" method="get"><div class="search-field"><i class="bi bi-search"></i><input name="q" value="<?= e($term) ?>" placeholder="Search name, student number, program…"></div><div class="filter-control"><label for="face">FACE REGISTRATION</label><select id="face" name="face"><option value="">All statuses</option><option <?= $face==='Registered'?'selected':'' ?>>Registered</option><option <?= $face==='Pending'?'selected':'' ?>>Pending</option></select></div><button class="btn btn-primary filter-button">Apply filters</button><a href="students_manage.php" class="clear-filter">Reset</a></form><div class="table-responsive"><table class="table activity-table"><thead><tr><th>STUDENT</th><th>STUDENT NUMBER</th><th>PROGRAM / SECTION</th><th>ENROLLED CLASSES</th><th>FACE PROFILE</th><th>UPDATED</th><th>ACTIONS</th></tr></thead><tbody>
<?php if(!$students): ?><tr><td colspan="7" class="empty-state">No students match this filter. Add a student to get started.</td></tr><?php else: foreach($students as $s): ?><tr><td><div class="student-cell"><span class="avatar student-avatar"><?= e(initials($s['full_name'])) ?></span><span><strong><?= e($s['full_name']) ?></strong><small class="d-block camera-status"><?= e($s['email']) ?></small></span></div></td><td class="table-secondary-text"><?= e($s['student_number']) ?></td><td><strong><?= e($s['program_year']) ?></strong><small class="d-block camera-status"><?= e($s['section']) ?></small></td><td class="table-secondary-text"><?= e($s['classes']?:'Not enrolled') ?></td><td><?= status_badge($s['face_status']) ?></td><td class="table-secondary-text"><?= e(date('M j, Y',strtotime($s['updated_at']))) ?></td><td><div class="d-flex gap-1"><button class="btn btn-sm btn-outline-secondary" data-bs-toggle="modal" data-bs-target="#studentModal" onclick='editStudent(<?= json_encode(['id'=>(int)$s['id'],'full_name'=>$s['full_name'],'email'=>$s['email'],'student_number'=>$s['student_number'],'program_year'=>$s['program_year'],'section'=>$s['section'],'class_ids'=>array_map('intval',explode(',',(string)$s['class_ids']))],JSON_HEX_APOS|JSON_HEX_QUOT|JSON_HEX_TAG|JSON_HEX_AMP) ?>)' aria-label="Edit <?= e($s['full_name']) ?>"><i class="bi bi-pencil"></i></button><button class="btn btn-sm btn-outline-danger" data-bs-toggle="modal" data-bs-target="#deleteStudent<?= (int)$s['id'] ?>" aria-label="Remove <?= e($s['full_name']) ?>"><i class="bi bi-trash3"></i></button></div></td></tr>
<div class="modal fade" id="deleteStudent<?= (int)$s['id'] ?>" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered modal-sm"><form method="post" class="modal-content"><?= csrf_field() ?><input type="hidden" name="action" value="delete"><input type="hidden" name="student_id" value="<?= (int)$s['id'] ?>"><div class="modal-body text-center p-4"><span class="stat-icon icon-red mx-auto mb-3"><i class="bi bi-trash3"></i></span><h2 class="h6">Remove student?</h2><p class="camera-status"><?= $role==='admin'?'This removes the student account, enrollments, and attendance history.':'This removes the student from your classes.' ?></p><div class="d-flex gap-2"><button type="button" class="btn btn-outline-secondary flex-fill" data-bs-dismiss="modal">Cancel</button><button class="btn btn-danger flex-fill">Remove</button></div></div></form></div></div>
<?php endforeach; endif; ?></tbody></table></div><div class="table-footer"><span>Showing up to 200 student records</span><span>Student directory</span></div></section>
<section class="content-card mt-3"><div class="card-heading"><div><h2>Class directory</h2><p>Course schedule and teaching assignments</p></div></div><div class="table-responsive"><table class="table activity-table"><thead><tr><th>CLASS</th><th>SUBJECT</th><th>INSTRUCTOR</th><th>SCHEDULE</th><th>ROOM</th><th>ENROLLED</th></tr></thead><tbody><?php foreach($classes as $class): $count=$pdo->prepare('SELECT COUNT(*) FROM enrollments WHERE class_id=?');$count->execute([$class['id']]); ?><tr><td><strong><?= e($class['class_code']) ?></strong></td><td><?= e($class['subject_name']) ?></td><td class="table-secondary-text"><?= e($class['teacher_name']??'Assigned instructor') ?></td><td class="table-secondary-text"><?= e($class['schedule_day'].' · '.date('g:i A',strtotime($class['start_time'])).'–'.date('g:i A',strtotime($class['end_time']))) ?></td><td class="table-secondary-text"><?= e($class['room']) ?></td><td><?= (int)$count->fetchColumn() ?></td></tr><?php endforeach; ?></tbody></table></div></section>
<div class="modal fade" id="studentModal" tabindex="-1" aria-hidden="true"><div class="modal-dialog modal-dialog-centered"><form method="post" class="modal-content" id="studentForm"><?= csrf_field() ?><input type="hidden" name="action" value="save"><input type="hidden" name="student_id" id="student_id" value="0"><div class="modal-header"><div><h2 class="modal-title" id="studentModalTitle">Add student</h2><p class="camera-status mb-0 mt-1">Create a student profile and assign an initial class.</p></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-12"><label class="field-label" for="studentName">FULL NAME</label><input class="form-control" id="studentName" name="full_name" required></div><div class="col-12"><label class="field-label" for="studentEmail">EMAIL</label><input class="form-control" id="studentEmail" name="email" type="email" required></div><div class="col-md-6"><label class="field-label" for="studentNumber">STUDENT NUMBER</label><input class="form-control" id="studentNumber" name="student_number" required></div><div class="col-md-6"><label class="field-label" for="studentSection">SECTION</label><input class="form-control" id="studentSection" name="section" required></div><div class="col-12"><label class="field-label" for="studentProgram">PROGRAM AND YEAR</label><input class="form-control" id="studentProgram" name="program_year" placeholder="BSIT · Year 2" required></div><div class="col-12"><label class="field-label" for="studentClass">ASSIGN TO CLASS</label><select class="form-select" id="studentClass" name="class_id" required><option value="">Choose class</option><?php foreach($classes as $class): ?><option value="<?= (int)$class['id'] ?>"><?= e($class['class_code'].' · '.$class['subject_name']) ?></option><?php endforeach; ?></select></div><div class="col-12" id="passwordField"><label class="field-label" for="studentPassword">INITIAL PASSWORD</label><input class="form-control" id="studentPassword" name="password" type="password" minlength="8" placeholder="At least 8 characters"><div class="form-text">Share this initial password securely. The student can change it in their profile.</div></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" id="studentSave">Create student</button></div></form></div></div>
<script>
function prepareStudentModal(){const f=document.getElementById('studentForm');if(f.dataset.editing==='1')return;f.reset();f.dataset.editing='0';document.getElementById('student_id').value='0';document.getElementById('studentModalTitle').textContent='Add student';document.getElementById('studentSave').textContent='Create student';document.getElementById('passwordField').classList.remove('d-none');document.getElementById('studentPassword').required=true}
function editStudent(s){const f=document.getElementById('studentForm');f.dataset.editing='1';document.getElementById('student_id').value=s.id;document.getElementById('studentName').value=s.full_name;document.getElementById('studentEmail').value=s.email;document.getElementById('studentNumber').value=s.student_number;document.getElementById('studentProgram').value=s.program_year;document.getElementById('studentSection').value=s.section;document.getElementById('studentClass').value=(s.class_ids.find(id=><?= json_encode($managedIds) ?>.includes(id))||'');document.getElementById('studentPassword').required=false;document.getElementById('passwordField').classList.add('d-none');document.getElementById('studentModalTitle').textContent='Edit student';document.getElementById('studentSave').textContent='Save changes'}
document.getElementById('studentModal')?.addEventListener('hidden.bs.modal',()=>{const f=document.getElementById('studentForm');f.dataset.editing='0';});
</script>
<?php page_end(); ?>
